changeSet.sql:
ALTER TABLE nexus.topic_assignments NO FORCE ROW LEVEL SECURITY; ALTER TABLE nexus.chunks NO FORCE ROW LEVEL SECURITY;
DO $$ DECLARE v_backfilled_count BIGINT; v_ambiguous_count BIGINT; v_unresolvable_count BIGINT; BEGIN -- (b) Unique-resolution backfill: set source_collection for NULL rows -- whose doc_id text-matches encode(chash,'hex') for EXACTLY ONE distinct -- collection in the same tenant. Never decode(doc_id,'hex') — a -- non-conformant doc_id simply cannot text-equal a 64-lowercase-hex -- encode() output, so this can never raise regardless of doc_id shape. -- Restricted to CANONICAL 64-hex doc_id candidates only (the shape every -- live writer emits, D1's own "structurally 64-hex" finding): a -- non-conformant doc_id is NEVER a backfill candidate, even if it -- happens to text-match a chunk by coincidence (a stray legacy-width -- nexus.chunks row that predates its own octet-width remediation) -- -- resolving a garbage doc_id into a real-looking FK-satisfying row would -- be exactly the silent-widening-to-admit-a-bad-row fallback D0.9 -- forbids. Every such row instead falls through to the UNRESOLVABLE -- arm below, unconditionally. UPDATE nexus.topic_assignments ta SET source_collection = ur.collection FROM ( SELECT tenant_id, doc_id, MIN(collection) AS collection FROM ( SELECT DISTINCT ta2.tenant_id, ta2.doc_id, c.collection FROM nexus.topic_assignments ta2 JOIN nexus.chunks c ON c.tenant_id = ta2.tenant_id AND encode(c.chash, 'hex') = ta2.doc_id WHERE ta2.source_collection IS NULL AND ta2.doc_id ~ '^[0-9a-f]{64}$' ) candidate GROUP BY tenant_id, doc_id HAVING COUNT(*) = 1 ) ur WHERE ta.tenant_id = ur.tenant_id AND ta.doc_id = ur.doc_id AND ta.source_collection IS NULL; GET DIAGNOSTICS v_backfilled_count = ROW_COUNT; RAISE NOTICE 'RDR-194 P3b source_collection backfill (nexus-tk070.p3b): backfilled % row(s) with a unique-resolution collection', v_backfilled_count;
-- (c) Counted DELETE of the AMBIGUOUS remainder: the doc_id's chash is -- present under MORE THAN ONE distinct collection for the tenant, so it -- cannot be attributed after the fact. Semi-join via self-join, never a -- count comparison. DELETE FROM nexus.topic_assignments ta WHERE ta.source_collection IS NULL AND EXISTS ( SELECT 1 FROM nexus.chunks c1 JOIN nexus.chunks c2 ON c2.tenant_id = c1.tenant_id AND c2.chash = c1.chash AND c2.collection != c1.collection WHERE c1.tenant_id = ta.tenant_id AND encode(c1.chash, 'hex') = ta.doc_id ); GET DIAGNOSTICS v_ambiguous_count = ROW_COUNT; RAISE NOTICE 'RDR-194 P3b source_collection backfill (nexus-tk070.p3b): deleted % ambiguous row(s) (doc_id chash present under more than one collection)', v_ambiguous_count;
-- (c) Counted DELETE of the UNRESOLVABLE remainder: shape-agnostic by -- construction (HAL directive 2026-08-16). CORRECTED 2026-08-17 -- (critical fix round, critic CRITICAL / bead nexus-i3k3e): the -- SHAPE-INVALID branch below is UNCONDITIONAL on source_collection — -- it is NOT scoped by `ta.source_collection IS NULL` — because Hal's -- own no-wedge directive is unambiguous on this point: "a -- non-canonical doc_id row is unrecomputable garbage REGARDLESS of -- its source_collection." The original version of this DELETE scoped -- BOTH the shape check and the anti-join to `source_collection IS -- NULL`, which the cc4 census (T2 nexus/rdr194-cc4-census-2026-08-16) -- proved wrong on real cloud data: of cc4's 5,896 legacy 32-hex rows, -- only 4,634 have source_collection IS NULL — the remaining 1,262 -- ALREADY carry a non-NULL source_collection (set by the pre-P3a -- projection/cross-collection writer branch, which always persisted -- source_collection even for a non-canonical doc_id) and were -- silently skipped by the NULL-scoped predicate, surviving -- unremediated into taxonomy-011-1's guard where they deterministically -- RAISE EXCEPTION with a remedy ("re-run taxonomy-010-1") that changes -- nothing for them — a genuine wedge, not a hypothetical. -- -- The ANTI-JOIN branch (a canonical-64-hex doc_id with no backing -- nexus.chunks row) stays NULL-scoped, deliberately NOT widened: a -- shape-VALID doc_id with a missing chunk match is a DIFFERENT failure -- mode (a dangling reference, not a malformed identifier) that -- taxonomy-011-1's guard does not even check (the guard is a pure -- regex shape test) — widening it would delete rows this phase has -- no wedge-risk reason to touch, silent scope creep beyond the fix -- this round exists to make. Likewise the AMBIGUOUS delete arm above -- and the (b) backfill arm stay NULL-scoped as originally designed — -- neither can ever match a shape-invalid doc_id in the first place (a -- 32-hex value cannot text-equal any encode(chash,'hex') of a 32-byte -- chash, which is always exactly 64 hex characters), so widening -- either would be a no-op for THIS bug and is not attempted. -- -- Never decodes, so it never raises on ANY doc_id shape a user install -- accumulated — absorbs ALL of cc4's 5,896 legacy 32-hex rows (T2 -- nexus/rdr194-cc4-census-2026-08-16), 4,634 NULL-scoped plus 1,262 -- non-NULL, unconditionally, along with every other unresolvable -- shape. DELETE FROM nexus.topic_assignments ta WHERE ta.doc_id !~ '^[0-9a-f]{64}$' OR ( ta.source_collection IS NULL AND NOT EXISTS ( SELECT 1 FROM nexus.chunks c WHERE c.tenant_id = ta.tenant_id AND encode(c.chash, 'hex') = ta.doc_id ) ); GET DIAGNOSTICS v_unresolvable_count = ROW_COUNT; RAISE NOTICE 'RDR-194 P3b source_collection backfill (nexus-tk070.p3b): deleted % unresolvable row(s) (non-conformant doc_id shape, REGARDLESS of source_collection, OR a NULL-source_collection row with no matching nexus.chunks row)', v_unresolvable_count; END $$;
ALTER TABLE nexus.chunks FORCE ROW LEVEL SECURITY; ALTER TABLE nexus.topic_assignments FORCE ROW LEVEL SECURITY;
